import{_ as t,o as a,c as o,ag as s}from"./chunks/framework.B7PviQjB.js";const r="/docs/images/slides/index-editor-overview.png",g=JSON.parse('{"title":"Slides","description":"Slides is the Wafflebase presentation editor, where you build a deck with your team and present it full screen.","frontmatter":{"title":"Slides","description":"Slides is the Wafflebase presentation editor, where you build a deck with your team and present it full screen.","type":"overview"},"headers":[],"relativePath":"slides/index.md","filePath":"slides/index.md"}'),i={name:"slides/index.md"};function n(l,e,d,h,c,u){return a(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="slides" tabindex="-1">Slides <a class="header-anchor" href="#slides" aria-label="Permalink to &quot;Slides&quot;">​</a></h1><p>Slides is the Wafflebase presentation editor, where you build a deck with your team and present it full screen.</p><p>Use it to:</p><ul><li>Build a deck from layouts, text, images, shapes, tables, and diagrams</li><li>Give every slide a consistent look with a theme, then fine-tune colors, fonts, and backgrounds</li><li>Add transitions and animations, then present from the browser or download the deck as PowerPoint or PDF</li></ul><p><img src="'+r+'" alt="Slides editor with the slide strip, toolbar, Format/Motion/Background/Theme buttons, canvas, and speaker notes"></p><h2 id="find-your-way-around" tabindex="-1">Find your way around <a class="header-anchor" href="#find-your-way-around" aria-label="Permalink to &quot;Find your way around&quot;">​</a></h2><ul><li><strong>Slide strip</strong> (left): every slide as a thumbnail. Click one to open it, drag to reorder, and right-click for slide actions.</li><li><strong>Toolbar</strong> (top): <strong>Undo</strong> and <strong>Redo</strong>, <strong>Format painter</strong>, the zoom menu (it reads <strong>Fit</strong> until you change it), <strong>Add slide</strong>, and insert tools. The middle of the toolbar changes with what you select: object controls for a shape or image, text controls while you type.</li><li><strong>Format</strong>, <strong>Motion</strong>, <strong>Background</strong>, and <strong>Theme</strong> (right end of the toolbar): each opens a panel on the right. When the toolbar runs out of room, such as on a narrow window or while an object is selected, they show as icons only.</li><li><strong>Canvas</strong> (center): the current slide, with rulers along the top and left.</li><li><strong>Speaker notes</strong> (below the canvas): private notes for each slide.</li><li><strong>Slideshow</strong> and <strong>Export</strong> (header): present the deck, or download it.</li></ul><p>The zoom menu offers <strong>Fit</strong>, 50%, 75%, 100%, 150%, and 200%. <strong>Fit</strong> sizes the slide to the window.</p><h2 id="get-started" tabindex="-1">Get started <a class="header-anchor" href="#get-started" aria-label="Permalink to &quot;Get started&quot;">​</a></h2><ol><li>In your workspace, click <strong>New &gt; New presentation</strong>. The deck opens on one title slide.</li><li>Click <strong>Click to add title</strong> and type. To add another slide, click <strong>Add slide</strong> (the + button) in the toolbar.</li><li>Click <strong>Share</strong> in the header to invite your team. See <a href="/docs/collaborate/share.html">Share a document</a>.</li></ol><p>For a guided first deck, follow <a href="/docs/slides/build-a-deck.html">Tutorial: build a deck</a>.</p><h2 id="tasks" tabindex="-1">Tasks <a class="header-anchor" href="#tasks" aria-label="Permalink to &quot;Tasks&quot;">​</a></h2><p><strong>Build slides</strong></p><ul><li><a href="/docs/slides/add-content.html#add-a-slide">Add, duplicate, delete, and reorder slides</a></li><li><a href="/docs/slides/add-content.html">Add text, images, and shapes</a></li><li><a href="/docs/slides/add-content.html#add-a-table">Add a table</a> or <a href="/docs/slides/add-content.html#connect-shapes">connect shapes with lines</a></li></ul><p><strong>Design</strong></p><ul><li><a href="/docs/slides/style-and-arrange.html">Change fill, border, and effects</a></li><li><a href="/docs/slides/style-and-arrange.html#align-and-distribute-objects">Align, group, and order objects</a></li><li><a href="/docs/slides/themes-and-layouts.html">Apply a theme, change layouts, and set backgrounds</a></li></ul><p><strong>Animate and present</strong></p><ul><li><a href="/docs/slides/animations.html">Add transitions and animations</a></li><li><a href="/docs/slides/present.html">Write speaker notes and present</a></li><li><a href="/docs/slides/present.html#download-the-deck">Download as PowerPoint or PDF</a></li></ul><p><strong>Work together</strong></p><ul><li><a href="/docs/collaborate/edit-together.html">Edit with others in real time</a></li><li><a href="/docs/collaborate/version-history.html">Restore an earlier version</a></li><li><a href="/docs/files/import-export.html">Import a PowerPoint file</a></li></ul><h2 id="on-a-phone" tabindex="-1">On a phone <a class="header-anchor" href="#on-a-phone" aria-label="Permalink to &quot;On a phone&quot;">​</a></h2><p>On a phone the slide strip moves below the slide and the toolbar collapses into bottom sheets. You can add slides, edit text, insert content, style objects, and present. Speaker notes and slide reordering are not available. See <a href="/docs/start/phone.html">Use Wafflebase on a phone</a>.</p><p>A share-link viewer sees the deck read-only. On a phone, a viewer swipes left or right to change slides.</p><h2 id="reference" tabindex="-1">Reference <a class="header-anchor" href="#reference" aria-label="Permalink to &quot;Reference&quot;">​</a></h2><ul><li><a href="/docs/slides/keyboard-shortcuts.html">Keyboard shortcuts</a></li><li><a href="/docs/slides/style-and-arrange.html#use-the-format-options-panel">Format options panel</a></li><li><a href="/docs/slides/themes-and-layouts.html#built-in-themes">Built-in themes and layouts</a></li></ul><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li><a href="/docs/slides/build-a-deck.html">Tutorial: build a deck</a> to make a three-slide deck in about 10 minutes.</li><li><a href="/docs/slides/add-content.html">Add text, images, and shapes</a> to fill in your slides.</li><li><a href="/docs/slides/present.html">Present a deck</a> when you are ready to show it.</li></ul>',27)])])}const m=t(i,[["render",n]]);export{g as __pageData,m as default};
